module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output reg wfull,
    output wire				rempty,
    output reg [WIDTH-1:0]	rdata
);

    reg [WIDTH-1:0] ram [0:DEPTH-1];
    reg [ADDR_WIDTH-1:0] wptr_sync, rptr_sync;

    reg [ADDR_WIDTH-1:0] wptr_reg1, wptr_reg2;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_reg1 <= 0;
        end else begin
            wptr_reg1 <= wptr_sync;
        end
    end
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_reg2 <= 0;
        end else begin
            wptr_reg2 <= wptr_reg1;
        end
    end

    reg [ADDR_WIDTH-1:0] rptr_reg1, rptr_reg2;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_reg1 <= 0;
        end else begin
            rptr_reg1 <= rptr_sync;
        end
    end
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_reg2 <= 0;
        end else begin
            rptr_reg2 <= rptr_reg1;
        end
    end

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_sync <= 0;
        end else if (winc && !wfull) begin
            wptr_sync <= wptr_sync + 1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_sync <= 0;
        end else if (rinc && !rempty) begin
            rptr_sync <= rptr_sync + 1;
        end
    end

    assign rempty = (wptr_sync == rptr_sync);
    assign wfull = ((wptr_reg2 == rptr_reg1) && (wptr_reg1 != 0));

    assign rdata = ram[rptr_sync];

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
